mapper.select:
select count(1) from `ry_rental`.`ry_rental_merchant_role`
where tenant_id = #{tenantId} and member_id = #{memberId} and status = 0 and is_delete = 0
  and role_id in #{roleId}

select role_id from `ry_rental`.`ry_rental_merchant_internal_notice_role`
where tenant_id = #{tenantId} and member_id = #{memberId}
  and internal_notice_id = #{noticeId} and is_delete = 0 order by role_id
